CREATE OR REPLACE FUNCTION ECAMS.TOPDEPTNAME(DEPTCD IN VARCHAR2)
RETURN VARCHAR2
IS
  TOPDEPTNM    VARCHAR2(100);

--본부부서추출

CURSOR REQ_CUR IS
   SELECT CM_DEPTCD,CM_UPDEPTCD,CM_DEPTNAME
     FROM (SELECT  * FROM CMM0100 WHERE CM_USEYN='Y')
    START WITH CM_DEPTCD=DEPTCD
    CONNECT BY PRIOR CM_UPDEPTCD=CM_DEPTCD;

BEGIN
    FOR REQ_FET IN REQ_CUR LOOP
        IF REQ_FET.CM_UPDEPTCD IS NULL THEN
           EXIT;
        END IF;
        TOPDEPTNM := REQ_FET.CM_DEPTNAME;
    END LOOP;
RETURN TOPDEPTNM;

END;